param([Parameter(Mandatory)][ValidatePattern('^r(45[6-9]|46[0-9]|470|471|472)[a-z]$')][string]$Revision,[Parameter(Mandatory)][string]$Details,[Parameter(Mandatory)][string]$Phase,[string]$FocusedLog)
$ErrorActionPreference='Stop'
$project=Split-Path -Parent $PSScriptRoot
. (Join-Path $PSScriptRoot 'evidence-json.ps1')
$logs=Join-Path $project 'logs\continuation-20261003'
$stage=$Revision.Substring(0,4)
function Pin($p){[ordered]@{path=$p;bytes=(Get-Item -LiteralPath $p).Length;sha256=(Get-FileHash -LiteralPath $p).Hash}}
function Check($p){if((Get-FileHash -LiteralPath $p.path).Hash -ne $p.sha256 -or ($p.bytes -and (Get-Item -LiteralPath $p.path).Length -ne $p.bytes)){throw ('Pin drift: '+$p.path)}}
$cp=Join-Path $logs "$stage-candidate.json";$c=Get-Content -LiteralPath $cp -Raw|ConvertFrom-Json;Check $c
foreach($p in $c.source_pins){Check $p;if((Get-FileHash -LiteralPath $p.snapshot).Hash -ne $p.sha256){throw 'Current source snapshot drift'}}
$build=@(Get-Content -LiteralPath (Join-Path $logs "$Revision-library-build.jsonl")|ForEach-Object{try{$_|ConvertFrom-Json}catch{}})
if(-not @($build|Where-Object{$_.reason -eq 'build-finished' -and $_.success}).Count){throw 'Library build failed'}
$libs=@($build|Where-Object{$_.reason -eq 'compiler-artifact' -and $_.target.name -eq 'lito_modern'}|ForEach-Object{$_.filenames}|Where-Object{$_ -like '*.rlib'});if($libs.Count -ne 1){throw 'Library count'}
$lib=Join-Path (Split-Path $c.path -Parent) "$stage-production.rlib";if(Test-Path -LiteralPath $lib){throw 'Already sealed'};[IO.File]::Copy($libs[0],$lib,$false);if((Get-FileHash -LiteralPath $lib).Hash -ne (Get-FileHash -LiteralPath $libs[0]).Hash){throw 'Lib copy drift'};$c|Add-Member production_library (Pin $lib)
$test=if($FocusedLog){Join-Path $logs $FocusedLog}else{Join-Path $logs "$Revision-consumer.stdout.log"};if([IO.File]::ReadAllText($test) -notmatch '1 passed; 0 failed; 0 ignored;'){throw 'Focused test failed'}
$dp=Join-Path $logs $Details;$d=Get-Content -LiteralPath $dp -Raw|ConvertFrom-Json;if($d.runtime_inputs_observed -or $d.renderer_LOADED -or $d.GUI -ne 0){throw 'Conditional scope mismatch'}
$ap=Join-Path $logs "$stage-original-source-pins.json";$asm=Get-Content -LiteralPath $ap -Raw|ConvertFrom-Json;Check $asm.original_disassembly;$text=[IO.File]::ReadAllText($asm.original_disassembly.path);foreach($p in $asm.files){Check $p;if(!$text.Contains([IO.File]::ReadAllText($p.path))){throw 'ASM not exact'}}
$snap=Get-Content -LiteralPath (Join-Path $logs 'r439-appearance-snapshot.json') -Raw|ConvertFrom-Json;if((Get-FileHash -LiteralPath (Join-Path $snap.candidate.root 'manifest.json')).Hash -ne $snap.candidate.manifest_sha256){throw 'Manifest drift'}
$resources=@(foreach($name in $d.input_pins.PSObject.Properties.Name){$p=Pin (Join-Path $snap.candidate.root $name);if($p.sha256 -ne $d.input_pins.$name.sha256 -or $p.bytes -ne $d.input_pins.$name.bytes){throw 'Resource drift'};$p});foreach($p in $d.extra_input_pins){Check $p};$images=@(foreach($p in $d.images){Check $p;Pin $p.path})
& (Join-Path $PSScriptRoot 'audit-continuation-source-scope.ps1')
$audit=Get-Content -LiteralPath (Join-Path $logs 'source-change-scope.json') -Raw|ConvertFrom-Json;$scope=Join-Path (Split-Path $c.path -Parent) "source-change-scope-$($audit.source_files).json";[IO.File]::Copy((Join-Path $logs 'source-change-scope.json'),$scope,$false)
$historical=@(foreach($old in @('r447','r448','r449','r450','r451','r452','r453','r454','r455')){$op=Join-Path $logs "$old-candidate.json";$o=Get-Content -LiteralPath $op -Raw|ConvertFrom-Json;Check $o;Check $o.production_library;foreach($s in $o.source_pins){if((Get-FileHash -LiteralPath $s.snapshot).Hash -ne $s.sha256){throw 'Historical snapshot drift'}};Pin $op})
$c.validation='PASSED one necessary focused continuous source branch/integration test; source/host/library/ASM/resources/images frozen; offline conditional only';Write-ModernEvidenceJson -Path $cp -Value $c
$result=Join-Path $logs "$stage-finite-renderer-result.json";Write-ModernEvidenceJson -Path $result -Value ([ordered]@{state=$d.state;candidate=$c;focused_passed=1;test=Pin $test;details=Pin $dp;ASM=Pin $ap;original_fragments=$asm.files.Count;selected_resources=$resources;extra_inputs=$d.extra_input_pins;images=$images;immutable_source_scope=Pin $scope;source_files=$audit.source_files;historical_protected=$historical;renderer_LOADED=$false;GUI=0;original_BIN_executed=$false;acceptance_coverage='16/40 unchanged';overall_status='in_progress'})
Write-ModernEvidenceJson -Path (Join-Path $logs "$stage-final-verification.json") -Value ([ordered]@{result=Pin $result;candidate=Pin $cp;host=Pin $c.path;library=Pin $lib;source_snapshots=$c.source_pins.Count;details=Pin $dp;immutable_scope=Pin $scope;renderer_LOADED=$false;GUI=0})
$sp=Join-Path (Split-Path $project -Parent) '監製進度.json';$status=Get-Content -LiteralPath $sp -Raw|ConvertFrom-Json;$status.updated_at=[DateTimeOffset]::Now.ToString('o');$status.phase=$Phase;$status.current_task="$stage focused continuous source branch passed; source $($audit.source_files), pinned $($c.source_pins.Count) source snapshots and $($asm.files.Count) whole ASM functions. $($images.Count) CPU outputs. Continue roof/mixed-scene necessary integration; runtime inputs/authority/native framebuffer/GUI remain unqualified; LOADEDfalse GUI0 16of40.";$status|Add-Member "native_$stage" (Pin $result) -Force;Write-ModernEvidenceJson -Path $sp -Value $status
Write-Output "$stage sealed: $($audit.source_files) sources; $($images.Count) CPU outputs; overall in progress"
